// KAHN'S TOPOLOGICAL SORT (BFS-based)
// O(V+E) time, O(V) space
function topoSortKahn(n, edges) {
    // Build adjacency list and compute in-degrees
    const adj = Array.from({length: n}, () => []);
    const inDegree = new Array(n).fill(0);

    for (const [u, v] of edges) {
        adj[u].push(v);
        inDegree[v]++;
    }

    // Queue: all vertices with in-degree 0
    const queue = [];
    for (let v = 0; v < n; v++) {
        if (inDegree[v] === 0) queue.push(v);
    }

    const result = [];
    while (queue.length) {
        const u = queue.shift(); // dequeue
        result.push(u);

        for (const v of adj[u]) {
            inDegree[v]--;              // one prerequisite done
            if (inDegree[v] === 0) {   // all prerequisites done
                queue.push(v);
            }
        }
    }

    // Cycle detection: if not all vertices processed, cycle exists
    return result.length === n ? result : null;
}

