// TOPOLOGICAL SORT WITH MULTIPLE VALID ORDERS:
// The specific order depends on which zero-in-degree vertex is dequeued first.
// Using a min-heap (priority queue) instead of a plain queue gives
// lexicographically smallest topological order.
function topoSortKahnLex(n, edges) {
    const adj = Array.from({length: n}, () => []);
    const inDeg = new Array(n).fill(0);
    for (const [u, v] of edges) { adj[u].push(v); inDeg[v]++; }

    // Min-heap for lexicographically smallest order
    const heap = [];
    for (let v = 0; v < n; v++) if (inDeg[v] === 0) heap.push(v);
    heap.sort((a,b) => a-b); // sorted as min-heap approximation

    const result = [];
    while (heap.length) {
        heap.sort((a,b) => a-b); // maintain sorted for lexicographic order
        const u = heap.shift();
        result.push(u);
        for (const v of adj[u]) {
            inDeg[v]--;
            if (inDeg[v] === 0) heap.push(v);
        }
    }
    return result.length === n ? result : null;
}

