// DFS-BASED TOPOLOGICAL SORT
// O(V+E) time, O(V) space
function topoSortDFS(n, edges) {
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) adj[u].push(v);

    const state = new Array(n).fill(0); // 0=unvisited, 1=in-path, 2=done
    const result = [];
    let hasCycle = false;

    function dfs(u) {
        if (hasCycle) return;
        state[u] = 1;                      // mark gray (in current path)
        for (const v of adj[u]) {
            if (state[v] === 1) { hasCycle = true; return; } // back edge: cycle
            if (state[v] === 0) dfs(v);    // unvisited: recurse
            // state[v] === 2: already fully processed, skip
        }
        state[u] = 2;                      // mark black (fully processed)
        result.push(u);                    // POST-ORDER: append AFTER all descendants
    }

    for (let v = 0; v < n; v++) {
        if (state[v] === 0) dfs(v);        // handle disconnected components
    }

    if (hasCycle) return null;
    return result.reverse();               // REVERSE post-order = topological order
}

