// COURSE SCHEDULE I (#207) — can all courses be completed?
function canFinish(numCourses, prerequisites) {
    // Build graph: [a,b] means b->a (b is prerequisite of a)
    const adj = Array.from({length: numCourses}, () => []);
    const inDeg = new Array(numCourses).fill(0);
    for (const [a, b] of prerequisites) {
        adj[b].push(a); // b->a: take b before a
        inDeg[a]++;
    }

    // Kahn's BFS
    const queue = [];
    for (let v = 0; v < numCourses; v++) if (inDeg[v] === 0) queue.push(v);
    let processed = 0;
    while (queue.length) {
        const u = queue.shift();
        processed++;
        for (const v of adj[u]) {
            if (--inDeg[v] === 0) queue.push(v);
        }
    }
    return processed === numCourses; // true if no cycle
}

// COURSE SCHEDULE II (#210) — return valid order
function findOrder(numCourses, prerequisites) {
    const adj = Array.from({length: numCourses}, () => []);
    const inDeg = new Array(numCourses).fill(0);
    for (const [a, b] of prerequisites) {
        adj[b].push(a);
        inDeg[a]++;
    }

    const queue = [];
    for (let v = 0; v < numCourses; v++) if (inDeg[v] === 0) queue.push(v);
    const order = [];
    while (queue.length) {
        const u = queue.shift();
        order.push(u);
        for (const v of adj[u]) {
            if (--inDeg[v] === 0) queue.push(v);
        }
    }
    return order.length === numCourses ? order : [];
}

