// ALIEN DICTIONARY (#269)
// O(V+E) time where V=unique chars, E=ordering rules derived
function alienOrder(words) {
    // Build graph and in-degree map for all chars in words
    const adj = new Map();
    const inDeg = new Map();
    // Initialise all characters
    for (const word of words) {
        for (const c of word) {
            if (!adj.has(c)) adj.set(c, new Set());
            if (!inDeg.has(c)) inDeg.set(c, 0);
        }
    }

    // Extract ordering rules from adjacent word pairs
    for (let i = 0; i < words.length - 1; i++) {
        const w1 = words[i], w2 = words[i+1];
        const minLen = Math.min(w1.length, w2.length);
        // Check for invalid case: longer word is prefix of shorter word
        if (w1.length > w2.length && w1.slice(0, minLen) === w2) return '';

        for (let j = 0; j < minLen; j++) {
            if (w1[j] !== w2[j]) {
                // w1[j] comes BEFORE w2[j] in alien alphabet
                if (!adj.get(w1[j]).has(w2[j])) {
                    adj.get(w1[j]).add(w2[j]);
                    inDeg.set(w2[j], inDeg.get(w2[j]) + 1);
                }
                break; // only first differing char gives ordering info
            }
        }
    }

    // Kahn's topological sort on character graph
    const queue = [];
    for (const [c, deg] of inDeg) {
        if (deg === 0) queue.push(c);
    }
    const result = [];
    while (queue.length) {
        queue.sort(); // lexicographic ordering (optional, for deterministic output)
        const c = queue.shift();
        result.push(c);
        for (const next of adj.get(c)) {
            inDeg.set(next, inDeg.get(next) - 1);
            if (inDeg.get(next) === 0) queue.push(next);
        }
    }
    // Cycle detection: if not all chars in result, invalid
    return result.length === inDeg.size ? result.join('') : '';
}

