// RECONSTRUCT ITINERARY (#332)
// O(E log E) time: sorting adjacency lists
function findItinerary(tickets) {
    // Build adjacency list: airport -> sorted list of destinations
    const adj = new Map();
    for (const [from, to] of tickets) {
        if (!adj.has(from)) adj.set(from, []);
        adj.get(from).push(to);
    }
    // Sort destinations lexicographically ASCENDING
    for (const [_, dests] of adj) dests.sort();
    // Note: we'll use pop() (O(1)) to take from the front of sorted array
    // So reverse sort to use pop() instead of shift()
    for (const [_, dests] of adj) dests.reverse(); // now smallest is at end

    const result = [];

    function dfs(airport) {
        const dests = adj.get(airport) || [];
        while (dests.length) {
            const next = dests.pop(); // take smallest (reversed, so pop = smallest)
            dfs(next);               // recurse into next airport
        }
        result.push(airport); // POST-ORDER: append after all edges exhausted
    }

    dfs('JFK');
    return result.reverse(); // reverse post-order = correct itinerary order
}

