// MINIMUM HEIGHT TREES (#310) — Kahn-style leaf pruning
// Find all roots that minimise tree height = trim leaves iteratively
function findMinHeightTrees(n, edges) {
    if (n === 1) return [0];
    const adj = Array.from({length: n}, () => new Set());
    for (const [u, v] of edges) { adj[u].add(v); adj[v].add(u); }

    let leaves = [];
    for (let i = 0; i < n; i++) if (adj[i].size === 1) leaves.push(i);

    let remaining = n;
    while (remaining > 2) {
        remaining -= leaves.length;
        const newLeaves = [];
        for (const leaf of leaves) {
            const neighbour = [...adj[leaf]][0];
            adj[neighbour].delete(leaf);
            if (adj[neighbour].size === 1) newLeaves.push(neighbour);
        }
        leaves = newLeaves;
    }
    return leaves; // 1 or 2 centroid nodes
}

